{

    struct l2cap_chan_s *chan = (struct l2cap_chan_s *) parm;



    if (len > chan->params.remote_mtu) {

        fprintf(stderr, "%s: B-Frame for CID %04x longer than %i octets.\n",

                        __func__,

                        chan->remote_cid, chan->params.remote_mtu);

        exit(-1);

